package finance.data.serializer;

import finance.commodity.CommodityRegistry;
import finance.config.FinanceConfig;
import finance.futures.*;
import net.minecraft.nbt.*;

import java.math.BigInteger;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.*;

/** Bounded futures persistence. Load order is contracts, margin/positions, orders/trades, then clearing state. */
public final class FuturesDataSerializer {
    private static final int MAX_ACCOUNTS=10_000,MAX_POSITIONS=100_000;
    private FuturesDataSerializer(){}
    public static void save(CompoundTag root){CompoundTag state=new CompoundTag();
        ListTag contracts=new ListTag();for(FuturesContract c:FuturesMarketManager.contracts().values()){CompoundTag t=new CompoundTag();t.putUUID("Id",c.id());t.putString("Code",c.code());t.putString("Commodity",c.commodityId());t.putLong("Size",c.contractSize());t.putLong("Listing",c.listingDay());t.putLong("LastTrading",c.lastTradingDay());t.putLong("Maturity",c.maturityDay());t.putString("SettlementType",c.settlementType().name());t.putString("Status",c.status().name());t.putLong("FinalPrice",c.finalSettlementPrice());contracts.add(t);}state.put("Contracts",contracts);
        ListTag accounts=new ListTag();for(MarginAccount a:MarginManager.accounts().values()){CompoundTag t=new CompoundTag();t.putUUID("Owner",a.ownerId());t.putLong("Cash",a.cashBalance());t.putLong("Frozen",a.frozenForOrders());t.putString("Risk",a.riskStatus().name());t.putLong("LastSettlement",a.lastSettlementDay());t.putLong("Notified",a.marginCallNotifiedDay());accounts.add(t);}state.put("Accounts",accounts);
        ListTag positions=new ListTag();for(FuturesPosition p:MarginManager.positions().values()){CompoundTag t=new CompoundTag();t.putUUID("Owner",p.ownerId());t.putUUID("Contract",p.contractId());t.putLong("Signed",p.signedQuantity());t.putLong("Average",p.averageEntryPrice());t.putLong("Reference",p.settlementReferencePrice());t.putLong("Realized",p.realizedPnl());t.putLong("Pending",MarginManager.pendingVariations().getOrDefault(new MarginManager.Key(p.ownerId(),p.contractId()),0L));positions.add(t);}for(var e:MarginManager.pendingVariations().entrySet())if(MarginManager.findPosition(e.getKey().ownerId(),e.getKey().contractId())==null){CompoundTag t=new CompoundTag();t.putUUID("Owner",e.getKey().ownerId());t.putUUID("Contract",e.getKey().contractId());t.putLong("Pending",e.getValue());positions.add(t);}state.put("Positions",positions);
        state.putLong("NextSequence",FuturesMarketManager.nextSequence());ListTag orders=new ListTag();for(FuturesOrder o:FuturesMarketManager.orders()){CompoundTag t=new CompoundTag();t.putUUID("Id",o.orderId());t.putUUID("Owner",o.playerId());t.putUUID("Contract",o.contractId());t.putString("Side",o.side().name());t.putLong("Price",o.limitPrice());t.putLong("Quantity",o.remainingQuantity());t.putLong("Sequence",o.sequence());t.putLong("Reserved",o.reservedMargin());orders.add(t);}state.put("Orders",orders);
        ListTag trades=new ListTag();for(FuturesTrade x:FuturesMarketManager.trades()){CompoundTag t=new CompoundTag();t.putUUID("Buyer",x.buyerId());t.putUUID("Seller",x.sellerId());t.putUUID("Contract",x.contractId());t.putLong("Price",x.price());t.putLong("Quantity",x.quantity());t.putLong("Day",x.mcDay());t.putLong("Time",x.timestamp().toEpochSecond(ZoneOffset.UTC));trades.add(t);}state.put("Trades",trades);
        state.putLong("GuaranteeFund",FuturesClearingService.guaranteeFund());state.putLong("TodayFundUse",FuturesClearingService.todayFundUse());state.putLong("LastRiskDay",FuturesClearingService.lastRiskDay());ListTag settlements=new ListTag();for(FuturesContract c:FuturesMarketManager.contracts().values()){long day=FuturesClearingService.lastSettlementDay(c.id()),price=FuturesClearingService.lastSettlementPrice(c.id());if(day>=0&&price>0){CompoundTag t=new CompoundTag();t.putUUID("Contract",c.id());t.putLong("Price",price);t.putLong("Day",day);settlements.add(t);}}state.put("Settlements",settlements);
        ListTag history=new ListTag();for(FuturesSettlementRecord x:FuturesClearingService.history()){CompoundTag t=new CompoundTag();t.putUUID("Contract",x.contractId());t.putLong("Day",x.day());t.putLong("Price",x.settlementPrice());t.putLong("Gain",x.grossGain());t.putLong("Collected",x.collectedLoss());t.putLong("FundUse",x.guaranteeFundUsed());t.putLong("Haircut",x.profitHaircut());t.putBoolean("Final",x.finalSettlement());history.add(t);}state.put("History",history);root.put("Futures",state);
    }
    public static void load(CompoundTag root){FuturesMarketManager.clearDirect();MarginManager.clearDirect();FuturesClearingService.clearDirect();if(!root.contains("Futures",Tag.TAG_COMPOUND))return;CompoundTag state=root.getCompound("Futures");
        Set<UUID> contractIds=new HashSet<>();ListTag contracts=state.getList("Contracts",Tag.TAG_COMPOUND);for(int i=0;i<Math.min(FuturesMarketManager.MAX_CONTRACTS,contracts.size());i++){CompoundTag t=contracts.getCompound(i);UUID id=NbtDataSupport.readUuidOrNull(t,"Id");var st=NbtDataSupport.safeEnum(FuturesContractStatus.class,t.getString("Status"),null);var type=NbtDataSupport.safeEnum(FuturesSettlementType.class,t.getString("SettlementType"),null);long size=t.getLong("Size"),listing=t.getLong("Listing"),last=t.getLong("LastTrading"),maturity=t.getLong("Maturity");if(id==null||!contractIds.add(id)||!CommodityRegistry.isRegistered(t.getString("Commodity"))||size<=0)continue;try{FuturesContract c=new FuturesContract(id,t.getString("Code"),t.getString("Commodity"),size,listing,last,maturity,type,st);c.restoreFinalSettlementPrice(t.getLong("FinalPrice"));FuturesMarketManager.putContractDirect(c);}catch(IllegalArgumentException ignored){}}
        Set<UUID> owners=new HashSet<>();ListTag accounts=state.getList("Accounts",Tag.TAG_COMPOUND);for(int i=0;i<Math.min(MAX_ACCOUNTS,accounts.size());i++){CompoundTag t=accounts.getCompound(i);UUID owner=NbtDataSupport.readUuidOrNull(t,"Owner");var risk=NbtDataSupport.safeEnum(MarginRiskStatus.class,t.getString("Risk"),null);long cash=t.getLong("Cash"),frozen=t.getLong("Frozen");if(owner==null||!owners.add(owner)||risk==null||cash<0||frozen<0||frozen>cash)continue;try{MarginManager.putAccountDirect(new MarginAccount(owner,cash,frozen,risk,t.getLong("LastSettlement"),t.getLong("Notified")));}catch(IllegalArgumentException ignored){}}
        Map<UUID,BigInteger> netByContract=new HashMap<>();Set<MarginManager.Key> keys=new HashSet<>();ListTag positions=state.getList("Positions",Tag.TAG_COMPOUND);for(int i=0;i<Math.min(MAX_POSITIONS,positions.size());i++){CompoundTag t=positions.getCompound(i);UUID owner=NbtDataSupport.readUuidOrNull(t,"Owner"),contract=NbtDataSupport.readUuidOrNull(t,"Contract");MarginManager.Key key=new MarginManager.Key(owner,contract);long signed=t.getLong("Signed"),pending=t.getLong("Pending");if(owner==null||contract==null||!keys.add(key)||!MarginManager.accounts().containsKey(owner)||FuturesMarketManager.contract(contract)==null||signed==Long.MIN_VALUE)continue;try{if(signed!=0){FuturesPosition p=new FuturesPosition(owner,contract,signed,t.getLong("Average"),t.getLong("Reference"),t.getLong("Realized"));MarginManager.putPositionDirect(p);netByContract.merge(contract,BigInteger.valueOf(signed),BigInteger::add);}if(pending!=0)MarginManager.putPendingDirect(key,pending);}catch(IllegalArgumentException ignored){}}
        Set<UUID> imbalanced=new HashSet<>();netByContract.forEach((id,net)->{if(net.signum()!=0)imbalanced.add(id);});MarginManager.removeContractStateDirect(imbalanced);
        List<FuturesOrder> orderCandidates=new ArrayList<>();Set<UUID> orderIds=new HashSet<>();ListTag orders=state.getList("Orders",Tag.TAG_COMPOUND);long maxSeq=0;for(int i=0;i<Math.min(FinanceConfig.futuresMaxOrders(),orders.size());i++){CompoundTag t=orders.getCompound(i);UUID id=NbtDataSupport.readUuidOrNull(t,"Id"),owner=NbtDataSupport.readUuidOrNull(t,"Owner"),contract=NbtDataSupport.readUuidOrNull(t,"Contract");var side=NbtDataSupport.safeEnum(FuturesOrderSide.class,t.getString("Side"),null);long price=t.getLong("Price"),qty=t.getLong("Quantity"),seq=t.getLong("Sequence"),reserved=t.getLong("Reserved");FuturesContract c=FuturesMarketManager.contract(contract);if(id==null||!orderIds.add(id)||owner==null||!MarginManager.accounts().containsKey(owner)||c==null||!c.canTrade()||side==null||price<=0||qty<=0||seq<=0||reserved<0||FuturesMath.notional(price,c.contractSize(),qty)<0)continue;try{orderCandidates.add(new FuturesOrder(id,owner,contract,side,price,qty,seq,reserved));maxSeq=Math.max(maxSeq,seq);}catch(IllegalArgumentException ignored){}}
        if(orderLocksMatch(orderCandidates))orderCandidates.forEach(FuturesMarketManager::addOrderDirect);else for(MarginAccount a:MarginManager.accounts().values())if(a.frozenForOrders()>0)MarginManager.releaseOrder(a.ownerId(),a.frozenForOrders());long stored=state.getLong("NextSequence");FuturesMarketManager.restoreSequence(Math.max(stored,maxSeq==Long.MAX_VALUE?Long.MAX_VALUE:maxSeq+1));
        ListTag trades=state.getList("Trades",Tag.TAG_COMPOUND);int start=Math.max(0,trades.size()-FuturesMarketManager.MAX_TRADES);for(int i=start;i<trades.size();i++){CompoundTag t=trades.getCompound(i);UUID b=NbtDataSupport.readUuidOrNull(t,"Buyer"),s=NbtDataSupport.readUuidOrNull(t,"Seller"),c=NbtDataSupport.readUuidOrNull(t,"Contract");long price=t.getLong("Price"),qty=t.getLong("Quantity"),day=t.getLong("Day");if(b==null||s==null||FuturesMarketManager.contract(c)==null||price<=0||qty<=0||day<0)continue;try{FuturesMarketManager.addTradeDirect(new FuturesTrade(b,s,c,price,qty,day,LocalDateTime.ofEpochSecond(t.getLong("Time"),0,ZoneOffset.UTC)));}catch(RuntimeException ignored){}}
        FuturesClearingService.restoreFund(state.getLong("GuaranteeFund"),state.getLong("TodayFundUse"),state.getLong("LastRiskDay"));ListTag settlements=state.getList("Settlements",Tag.TAG_COMPOUND);for(int i=0;i<Math.min(FuturesMarketManager.MAX_CONTRACTS,settlements.size());i++){CompoundTag t=settlements.getCompound(i);UUID c=NbtDataSupport.readUuidOrNull(t,"Contract");if(FuturesMarketManager.contract(c)!=null&&t.getLong("Price")>0&&t.getLong("Day")>=0)FuturesClearingService.putSettlementDirect(c,t.getLong("Price"),t.getLong("Day"));}ListTag history=state.getList("History",Tag.TAG_COMPOUND);int hs=Math.max(0,history.size()-FuturesClearingService.MAX_HISTORY);for(int i=hs;i<history.size();i++){CompoundTag t=history.getCompound(i);UUID c=NbtDataSupport.readUuidOrNull(t,"Contract");try{if(FuturesMarketManager.contract(c)!=null)FuturesClearingService.addHistoryDirect(new FuturesSettlementRecord(c,t.getLong("Day"),t.getLong("Price"),t.getLong("Gain"),t.getLong("Collected"),t.getLong("FundUse"),t.getLong("Haircut"),t.getBoolean("Final")));}catch(IllegalArgumentException ignored){}}
    }
    private static boolean orderLocksMatch(List<FuturesOrder> orders){Map<UUID,BigInteger> sums=new HashMap<>();for(FuturesOrder o:orders)sums.merge(o.playerId(),BigInteger.valueOf(o.reservedMargin()),BigInteger::add);for(MarginAccount a:MarginManager.accounts().values())if(sums.getOrDefault(a.ownerId(),BigInteger.ZERO).compareTo(BigInteger.valueOf(a.frozenForOrders()))!=0)return false;return true;}
}
